#include "replay.hpp"
#include <gtest/gtest.h>
#ifndef P1_REPLAY_INPUT_FILE
#error pinned actual input file required
#endif
namespace {
using Json=bias_replay::Json;
Json data(){return bias_replay::read(P1_REPLAY_INPUT_FILE);}
TEST(ReferenceReplay,ActualCompleteWarmPrefixHasNoMissingNativeJob){const auto d=data();ASSERT_EQ(d["ordered_native_jobs"].size(),104u);for(size_t k=0;k<104;++k)EXPECT_EQ(d["ordered_native_jobs"][k]["job"]["job_id"],k+1);EXPECT_EQ(d["selected_job_id"],104);}
TEST(ReferenceReplay,CounterfactualChangesOnlyWholeReferenceXOrigin){const auto j=data()["ordered_native_jobs"].back()["job"];auto changed=bias_replay::shift_reference_x_to_target(j);auto restored=changed;restored["reference"]=j["reference"];EXPECT_EQ(restored,j);EXPECT_DOUBLE_EQ(changed["reference"][0],j["target_state"][0]);const double delta=changed["reference"][0].get<double>()-j["reference"][0].get<double>();for(size_t k=0;k<126;++k)if(k%6)EXPECT_EQ(changed["reference"][k],j["reference"][k]);else EXPECT_NEAR(changed["reference"][k].get<double>()-j["reference"][k].get<double>(),delta,1e-14);}
TEST(ReferenceReplay,StateAnchorAndVelocityReferenceRemainActualBitValues){const auto j=data()["ordered_native_jobs"].back()["job"],c=bias_replay::shift_reference_x_to_target(j);EXPECT_EQ(c["target_state"],j["target_state"]);EXPECT_EQ(c["frozen_state"],j["frozen_state"]);EXPECT_EQ(c["anchor_n"],j["anchor_n"]);for(size_t k=0;k<21;++k)EXPECT_EQ(c["reference"][6*k+3],j["reference"][6*k+3]);}
TEST(ReferenceReplay,EquilibriumPointOneHasExactZeroBodyAcceleration){auto p=bias_replay::parameters(data()["contract"]);usv_mpc::Vector6d x=usv_mpc::Vector6d::Zero();x[3]=.1;auto u=Eigen::Vector2d::Constant(bias_replay::equilibrium_thrust(.1,p.hydro));auto rhs=usv_mpc::USVDynamicModel::continuous_ode(x,u,p.hydro);EXPECT_NEAR(rhs[3],0.,1e-15);EXPECT_NEAR(rhs[4],0.,1e-15);EXPECT_NEAR(rhs[5],0.,1e-15);EXPECT_DOUBLE_EQ(rhs[0],.1);}
TEST(ReferenceReplay,EquilibriumPointOneTwoFiveUsesDifferentActualDragCommand){auto p=bias_replay::parameters(data()["contract"]);const double low=bias_replay::equilibrium_thrust(.1,p.hydro),high=bias_replay::equilibrium_thrust(.125,p.hydro);EXPECT_NEAR(low,.17146207,1e-12);EXPECT_NEAR(high,.2324085,1e-12);EXPECT_GT(high-low,.06);usv_mpc::Vector6d x=usv_mpc::Vector6d::Zero();x[3]=.125;auto rhs=usv_mpc::USVDynamicModel::continuous_ode(x,Eigen::Vector2d::Constant(high),p.hydro);EXPECT_NEAR(rhs[3],0.,1e-15);}
TEST(ReferenceReplay,NominalDiscreteEquilibriumPreservesSpeedAndMovesPosition){auto p=bias_replay::parameters(data()["contract"]);usv_mpc::USVDynamicModel model(p.dt,4,p.hydro);for(double speed:{.1,.125}){usv_mpc::Vector6d x=usv_mpc::Vector6d::Zero();x[3]=speed;auto end=model.forward(x,Eigen::Vector2d::Constant(bias_replay::equilibrium_thrust(speed,p.hydro)));EXPECT_NEAR(end[0],speed*p.dt,1e-14);EXPECT_NEAR(end[3],speed,1e-14);}}
TEST(ReferenceReplay,StageControlCostIsDtScaledAndIncrementIsNotRate){auto p=bias_replay::parameters(data()["contract"]);usv_mpc::SolveInfo info;info.X_pred=Eigen::MatrixXd::Zero(6,21);info.U_pred=Eigen::MatrixXd::Ones(2,20);auto cost=bias_replay::objective(info,Eigen::MatrixXd::Zero(6,21),Eigen::Vector2d::Zero(),p);EXPECT_NEAR(cost["stage_absolute_control_dt_scaled"].get<double>(),.4,1e-12);EXPECT_NEAR(cost["stage_control_increment_dt_scaled"].get<double>(),.08,1e-12);}
TEST(ReferenceReplay,TerminalStateCostDoesNotMultiplyDt){auto p=bias_replay::parameters(data()["contract"]);usv_mpc::SolveInfo info;info.X_pred=Eigen::MatrixXd::Zero(6,21);info.U_pred=Eigen::MatrixXd::Zero(2,20);info.X_pred(0,20)=1.;auto cost=bias_replay::objective(info,Eigen::MatrixXd::Zero(6,21),Eigen::Vector2d::Zero(),p);EXPECT_DOUBLE_EQ(cost["terminal_state_not_dt_scaled"].get<double>(),160.);}
TEST(ReferenceReplay,ActualBackendCompleteWarmPrefixNumericallyMatchesRecordedNativeOutput){auto r=bias_replay::prefix_replay(data(),false);EXPECT_EQ(r["jobs_replayed"],104);EXPECT_LT(r["maximum_absolute_baseline_first_control_error"].get<double>(),1e-8);EXPECT_LT(r["maximum_absolute_baseline_X_error"].get<double>(),1e-7);EXPECT_LT(r["maximum_absolute_baseline_U_error"].get<double>(),1e-7);}
} // namespace
